script:
# The Vermont Statutes: every title, every chapter, one "fullchapter" page each. A section is a <div> that opens with
# <b>§ 111. Annual meeting</b> and holds its paragraphs. Citation "{title} V.S.A.{app} § {id}" (title from the url: 01 -> 1, 09A -> 9A).
# (The first recipe flattened each section page and cut the heading off at random; it read titles 1-8 only. 2026-10-07)
import re, html
BASE = 'https://legislature.vermont.gov'
SEC = re.compile(r'<div>\s*<p[^>]*>\s*<b>\s*§§?\s*([0-9]+[0-9A-Za-z.\-]*)\.?\s*(.*?)</b>\s*</p>(.*?)</div>', re.S)
def plain(s):
    return re.sub(r'[ \t\r\n\xa0]+', ' ', html.unescape(re.sub(r'<[^>]+>', ' ', s))).strip()
def page(url):
    kind, body = fetch(url)
    return body if isinstance(body, str) else body.decode('utf-8', 'ignore')
def sections():
    titles = list(dict.fromkeys(re.findall(r'href=["\']/statutes/title/([0-9A-Z]+)["\']', page(BASE + '/statutes/'))))
    log('titles: ' + str(len(titles)))
    for t in titles:
        try:
            chapters = list(dict.fromkeys(re.findall(r'href=["\']/statutes/chapter/' + t + r'/([0-9A-Z]+)["\']', page(BASE + '/statutes/title/' + t))))
        except Exception as e:
            log('title failed ' + t + ' ' + repr(e)); continue
        title, app = (re.sub(r'APPENDIX$', '', t).lstrip('0') or '0'), (' App.' if t.endswith('APPENDIX') else '')   # 10APPENDIX -> 10 V.S.A. App.
        for ch in chapters:
            url = BASE + '/statutes/fullchapter/' + t + '/' + ch
            try:
                body = page(url)
            except Exception as e:
                log('chapter failed ' + t + '/' + ch + ' ' + repr(e)); continue
            for m in SEC.finditer(body):
                sid, heading = m.group(1).rstrip('.'), plain(m.group(2)).rstrip('.').strip()
                paras = [plain(p) for p in re.findall(r'<p[^>]*>(.*?)</p>', m.group(3), re.S)]
                text = '\n'.join(['§ ' + sid + '. ' + heading] + [p for p in paras if p])
                yield {'id': sid, 'heading': heading, 'text': text, 'url': url, 'vars': {'title': title, 'app': app}}
